const HEX = /^#[0-9a-f]{6}$/i;
const pick = (v: unknown, fallback: string) => (typeof v === 'string' && HEX.test(v) ? v : fallback);
const str = (v: unknown, fallback: string) => (typeof v === 'string' && v.trim() ? v : fallback);

